INSERT INTO `platform_settings` VALUES
(1,'Helena West Helena Schools AI Institute','The Cougar AI Playbook — Powered by OptimizED Strategic Solutions','Helena West Helena Schools AI Institute','Helena West Helena Schools AI Institute','A PK–12 professional learning platform for using Google Gemini responsibly to advance the three Helena West Helena Schools WIGs — Customer Service & Communication, PLC Implementation Fidelity, and ATLAS Academic Achievement. ','[\"Strands\",\"Courses\",\"Modules\",\"Role Lenses\"]','#0B2E4F','#C9A227','HWHS AI','OptimizedInstitute','2026-07-06 18:20:07','2026-07-07 21:29:59','How confident do you feel applying this module\'s strategies?','How relevant was this content to your role?','What would improve this module?','<p>HWHS AI Institute for Teaching and Learning </p><p>Developed by <a href=\"https://optimizedstrategicsolutions.com\" target=\"_blank\" rel=\"noopener\">OptimizED Strategic Solutions</a> </p><p>© 2026 OptimizED Strategic Solutions, Fargo, ND.</p>','{\"classroom\":null,\"leader\":\"School Leader\",\"sped\":null,\"support\":null,\"coach\":null,\"higher_ed\":\"Cabinet \\/ Central Office\"}','Gemini',NULL,NULL,NULL);
INSERT INTO `practice_prompts` VALUES
(1,'F1.1','classroom','Sign in to Gemini with your @hwhschools.org account',NULL,'Open gemini.google.com signed into your @hwhschools.org Workspace account. Ask Gemini: \'You are a gemini foundations coach for a Helena West Helena Schools teacher. Explain how generative AI actually works and where it makes things up in 5 short paragraphs I can read in one CTM Wednesday planning block.\' Then paste your response into a fresh Google Doc titled \'My Gemini Baseline\'.',0,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(2,'F1.1','classroom','Try a first prompt inside Google Docs',NULL,'Open a Google Doc. Use the Gemini side panel (Help me write). Ask it to draft a 3-sentence email to families about an upcoming DFA window — no student names, warm HWHS tone. Compare Gemini\'s draft to what you\'d write yourself.',1,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(3,'F1.1','classroom','Ask Gemini to explain its own limits',NULL,'Ask Gemini: \'What are 5 things you should NOT be trusted to do in a Helena West Helena Schools classroom without a teacher checking your work?\' Paste the reply into your CTM notes.',2,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(4,'F1.1','coach','Draft a CTM Wednesday intro to Gemini',NULL,'Draft a 10-minute CTM Wednesday opener that introduces Gemini to your team using the 4-element fidelity rubric as the frame (Agenda Monday 5 pm · CFA on schedule · DuFour 4 Qs · Tier 2/3 closure before next CFA). Use Gemini to generate the opener, then edit it in your own voice.',3,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(5,'F1.1','coach','Prompt library seed',NULL,'Ask Gemini to generate 8 starter prompts an HWHS coach can hand teachers this week, one per HITS domain, each ending with a CFA-facing action.',4,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(6,'F1.1','coach','Observation lens for Gemini use',NULL,'Draft a 5-item walkthrough lens for observing a teacher\'s first Gemini-supported lesson at HWHS. Anchor items to the Academic Playbook, not to the tool.',5,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(7,'F1.1','higher_ed','Cabinet baseline briefing',NULL,'Ask Gemini to draft a 1-page Cabinet briefing on \'What Gemini is, what it is not, and how it will show up in HWHS this year.\' The briefing must reference the three WIGs and the scorecard\'s FERPA posture. Edit to Superintendent voice before circulating.',6,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(8,'F1.1','higher_ed','Guiding Coalition talking points',NULL,'Use Gemini to generate 6 talking points for the next Guiding Coalition meeting on responsible AI use across HWHS. Each talking point must tie to a specific scorecard surface — Cabinet, Principal, CTM, Board, or Public.',7,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(9,'F1.1','higher_ed','Central Office policy skeleton',NULL,'Ask Gemini to draft a skeleton HWHS AI Acceptable Use Policy — sections only, no body text yet — that reflects: aggregated-only data, Google Workspace as the sanctioned surface, 24-hour response promise, and Board reporting cadence.',8,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(10,'F1.1','leader','Principal walkthrough note',NULL,'Draft a note from a principal to staff introducing Gemini for the semester. Reference the school\'s 30-Day Plan cycle and the CTM Wednesday cadence. No individual staff names.',9,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(11,'F1.1','leader','30-Day Plan alignment',NULL,'Ask Gemini to draft a 30-Day Plan Reset for a principal that names one Gemini-supported action per WIG. Reset must include \'if-we-hit / if-we-miss\' language.',10,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(12,'F1.1','leader','Faculty meeting deck',NULL,'Ask Gemini to outline a 20-minute faculty meeting on \'Gemini and the Cougar Way\' — 3 slides on why, 3 slides on how, 1 slide on the FERPA posture.',11,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(13,'F1.1','sped','Baseline for accessibility',NULL,'Ask Gemini how it can make Helena West Helena Schools instructional materials more accessible without violating IEP confidentiality. Ground the reply in UDL and the existing MTSS structure.',12,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(14,'F1.1','sped','First Gemini task for a SPED teacher',NULL,'Ask Gemini to draft 3 sentence starters and 1 graphic organizer for a UDL-aligned writing task, matched to an Arkansas standard you\'re teaching this week. No student names or IEP language.',13,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(15,'F1.1','sped','IEP-safe workflow rules',NULL,'Ask Gemini to write a 5-rule \'safe workflow\' card for SPED staff at HWHS explaining what can and cannot be pasted into any AI tool.',14,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(16,'F1.1','support','Front office FAQ',NULL,'Ask Gemini to draft 10 FAQ entries for the HWHS front office on \'What is Gemini and why do we use it?\' The tone should match the Cougar family voice.',15,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(17,'F1.1','support','Bilingual family flyer',NULL,'Ask Gemini to draft a 1-page family flyer in English and Spanish introducing the HWHS AI Institute and the 24-hour response promise (WIG 1).',16,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
(18,'F1.1','support','Tutoring-time Gemini task',NULL,'Ask Gemini to draft a warm-up routine a Cougar Elevate afterschool tutor can use in the first 5 minutes of a session to get students settled and thinking.',17,'2026-07-07 01:50:08','2026-07-07 01:50:08',NULL),
